      activeProject: null
    }
  },
  computed: {
    // Unique project names from suggestions that have a project
    projectNames() {
      const names = this.suggestions
        .map(s => s.project?.project_name)
        .filter(Boolean)
      return [...new Set(names)]
    },
    // Filter suggestions by selected project
    filteredSuggestions() {
      if (!this.activeProject) return this.suggestions
      return this.suggestions.filter(s => s.project?.project_name === this.activeProject)
    },
    visibleSuggestions() {
      return this.filteredSuggestions.slice(0, this.maxVisible)
    }
