      }
    },
    // Use ring + bg only — no border toggling, no padding changes = zero layout shift
    itemClass(s, i) {
      const isActive = i === this.activeIndex
      const isHovered = i === this.hoveredIndex
      const selected = this.isSelected(s)

      if (selected) {
