      for (let i = 0; i < name.length; i++) {
        const ch = name[i]
        if (qi < q.length && ch.toLowerCase() === q[qi]) {
          result += `<span class="font-bold">${ch}</span>`
          qi++
        } else {
          result += ch
        }
      }
